{"path": "/tmp/sv-fa7387487d954dc89f4e43c4e174541b/Components/Pages/Chat/ChatPage.razor", "file_text": "@page "/chat"
@using sv_fa7387487d954dc89f4e43c4e174541b.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(IsThreadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea Channel="_activeChannel"
                 Messages="_messages"
                 ThreadReplyCounts="_threadReplyCounts"
                 IsLoadingMore="_isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages" />

    @if (IsThreadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = new();
    private List<Message> _messages = new();
    private List<Message> _threadReplies = new();
    private Dictionary<int, int> _threadReplyCounts = new();
    private Channel? _activeChannel;
    private Message? _threadRootMessage;
    private int _activeChannelId;
    private bool _isLoadingMore;
    private const int PageSize = 30;

    private bool IsThreadOpen => _threadRootMessage is not null;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _threadRootMessage = null;
        _threadReplies = new();
        await ChatService.MarkChannelReadAsync(channel.Id);
        await BuildThreadReplyCounts();
    }

    private async Task BuildThreadReplyCounts()
    {
        _threadReplyCounts = new();
        // Identify thread starters: messages that have replies pointing to them
        var replyTargets = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        foreach (var kvp in replyTargets)
        {
            _threadReplyCounts[kvp.Key] = kvp.Value;
        }

        await Task.CompletedTask;
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || _activeChannel is null) return;
        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            await BuildThreadReplyCounts();
        }
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var message = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(Message message)
    {
        _threadRootMessage = message;
        _threadReplies = await ChatService.GetThreadAsync(message.Id);
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadReplies = new();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (_activeChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, _messages.Count);
        }
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] =
            _threadReplyCounts.GetValueOrDefault(_threadRootMessage.Id) + 1;
    }
}
"}

