toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #fff;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    border-bottom: 1px solid #1e1f22;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 8px;
}

::deep .channel-item {
    padding: 8px 12px;
    border-radius: 6px;
    cursor: pointer;
    margin-bottom: 2px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 500;
    flex: 1;
}

::deep .channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #949ba4;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

::deep .unread-badge {
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #dbdee1;
    min-width: 0;
}

::deep .message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
